package my.waqt.app;
import android.app.*;import android.appwidget.*;import android.content.*;import android.widget.*;import org.json.*;import java.text.*;import java.util.*;
public class PrayerWidget extends AppWidgetProvider{
 static void updateAll(Context c){AppWidgetManager m=AppWidgetManager.getInstance(c);int[] ids=m.getAppWidgetIds(new ComponentName(c,PrayerWidget.class));for(int id:ids)update(c,m,id);}
 @Override public void onUpdate(Context c,AppWidgetManager m,int[] ids){for(int id:ids)update(c,m,id);}
 static void update(Context c,AppWidgetManager m,int id){RemoteViews v=new RemoteViews(c.getPackageName(),R.layout.prayer_widget);String zone=Alarms.prefs(c).getString("zone","");v.setTextViewText(R.id.widget_zone,zone.isEmpty()?"Malaysia":zone);String next="Buka Waqt",time="Pilih zon solat";try{JSONArray list=new JSONArray(Alarms.prefs(c).getString("slots","[]"));long now=System.currentTimeMillis(),best=Long.MAX_VALUE;String p="";for(int i=0;i<list.length();i++){JSONObject row=list.getJSONObject(i);long at=row.getLong("at");if(at>now&&at<best){best=at;p=row.getString("prayer");}}if(best!=Long.MAX_VALUE&&best-now<2*86400000L){SimpleDateFormat f=new SimpleDateFormat("EEE, HH:mm",new Locale("ms","MY"));f.setTimeZone(TimeZone.getTimeZone("Asia/Kuala_Lumpur"));next=p;time=f.format(new Date(best));}else if(!zone.isEmpty()){next="Jadual belum tersedia";time="Buka Waqt untuk kemas kini";}}catch(Exception ignored){}v.setTextViewText(R.id.widget_next,next);v.setTextViewText(R.id.widget_time,time);PendingIntent open=PendingIntent.getActivity(c,95,new Intent(c,MainActivity.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);v.setOnClickPendingIntent(R.id.widget_root,open);m.updateAppWidget(id,v);}
}